import { createContext, useContext, useEffect, useState, type ReactNode } from 'react';
import type { Session, User } from '@supabase/supabase-js';
import { supabase } from './supabaseClient';

interface AuthState {
  session: Session | null;
  user: User | null;
  loading: boolean;
  signIn: (email: string, password: string) => Promise<{ error: string | null }>;
  signUp: (email: string, password: string, displayName: string) => Promise<{ error: string | null; needsConfirmation: boolean }>;
  signOut: () => Promise<void>;
}

const AuthContext = createContext<AuthState | null>(null);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    supabase.auth.getSession().then(({ data }) => {
      setSession(data.session);
      setLoading(false);
    });
    const { data: sub } = supabase.auth.onAuthStateChange((_event, s) => {
      setSession(s);
      setLoading(false);
    });
    return () => sub.subscription.unsubscribe();
  }, []);

  const signIn: AuthState['signIn'] = async (email, password) => {
    const { error } = await supabase.auth.signInWithPassword({ email, password });
    return { error: error?.message ?? null };
  };

  const signUp: AuthState['signUp'] = async (email, password, displayName) => {
    const { data, error } = await supabase.auth.signUp({
      email,
      password,
      options: { data: { display_name: displayName } },
    });
    if (error) return { error: error.message, needsConfirmation: false };
    // Supabase returns no session when email confirmation is required.
    return { error: null, needsConfirmation: !data.session };
  };

  const signOut = async () => {
    await supabase.auth.signOut();
  };

  return (
    <AuthContext.Provider value={{ session, user: session?.user ?? null, loading, signIn, signUp, signOut }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used within AuthProvider');
  return ctx;
}
=== prefs ===
import { createContext, useContext, useEffect, useState, type ReactNode } from 'react';
import { useAuth } from './auth';
import { getProfile, updateProfile, type Profile } from './api';

interface PrefsState {
  profile: Profile | null;
  loading: boolean;
  reduceMotion: boolean;
  largerText: boolean;
  refresh: () => Promise<void>;
  save: (patch: Partial<Profile>) => Promise<void>;
}

const PrefsContext = createContext<PrefsState | null>(null);

export function ProfileProvider({ children }: { children: ReactNode }) {
  const { user } = useAuth();
  const [profile, setProfile] = useState<Profile | null>(null);
  const [loading, setLoading] = useState(true);

  const refresh = async () => {
    if (!user) {
      setProfile(null);
      setLoading(false);
      return;
    }
    setLoading(true);
    try {
      setProfile(await getProfile(user.id));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    refresh();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user?.id]);

  const save = async (patch: Partial<Profile>) => {
    if (!user) return;
    setProfile((prev) => (prev ? { ...prev, ...patch } : prev));
    await updateProfile(user.id, patch);
  };

  return (
    <PrefsContext.Provider
      value={{
        profile,
        loading,
        reduceMotion: profile?.reduce_motion ?? false,
        largerText: profile?.larger_text ?? false,
        refresh,
        save,
      }}
    >
      {children}
    </PrefsContext.Provider>
  );
}

export function usePrefs() {
  const ctx = useContext(PrefsContext);
  if (!ctx) throw new Error('usePrefs must be used within ProfileProvider');
  return ctx;
}
=== flow ===
/**
 * The order of the flow, in one place.
 *
 * Every screen reads its position from this array — the progress bar, the back
 * chevron and the next/previous transitions all derive from the index. Moving a
 * string moves the screen; no screen component knows what comes before or after
 * it.
 */
export const FLOW = [
  'welcome',
  'auth-choice',
  'auth-form',
  'profile',
  'info-library',
  'info-recs',
  'q1',
  'q2',
  'q3',
  'sleep',
  'meals',
  'current-stack',
  'goals',
  'notifications',
  'paywall',
  'building-recs',
  'recommendations',
  'building-schedule',
  'schedule',
  'done',
] as const;

export type Step = (typeof FLOW)[number];

/** Skip is offered on the three survey questions and nowhere else. */
export const SKIPPABLE: ReadonlySet<Step> = new Set<Step>(['q1', 'q2', 'q3']);

/** Welcome carries no chrome at all — no wordmark, no progress, no back. */
export const NO_CHROME: ReadonlySet<Step> = new Set<Step>(['welcome']);

/**
 * The two loading screens and the final confirmation drive themselves, so the
 * back chevron would strand the user mid-generation.
 */
export const NO_BACK: ReadonlySet<Step> = new Set<Step>([
  'welcome',
  'building-recs',
  'building-schedule',
  'done',
]);

export const indexOfStep = (s: Step): number => FLOW.indexOf(s);

/**
 * Steps that do not apply given what has been answered so far.
 *
 * Branching lives here rather than inside the screens, so the flow array stays
 * the single description of the order and a screen still never knows what
 * comes before or after it. Evaluated live on every move, so going back and
 * changing an answer re-opens whatever it closed.
 */
export function isSkipped(step: Step, answers: { q2: string | null }): boolean {
  // "What usually goes wrong?" has no answer for someone who has never
  // started a routine in the first place.
  if (step === 'q3' && answers.q2 === 'never') return true;
  return false;
}

export function nextStep(s: Step): Step | null {
  const i = FLOW.indexOf(s);
  return i >= 0 && i < FLOW.length - 1 ? FLOW[i + 1] : null;
}

export function prevStep(s: Step): Step | null {
  const i = FLOW.indexOf(s);
  return i > 0 ? FLOW[i - 1] : null;
}

