232	/** Groups the user's own logged injection sites by name — no interpretation, just a count and a most-recent date per site. */
233	export async function getInjectionSiteStats(userId: string): Promise<Record<string, InjectionSiteStat>> {
234	  const since = toISODate(new Date(Date.now() - 30 * 86_400_000));
235	  const { data, error } = await supabase
236	    .from('doses')
237	    .select('injection_site, log_date')
238	    .eq('user_id', userId)
239	    .not('injection_site', 'is', null)
240	    .gte('log_date', since)
241	    .order('log_date', { ascending: false });
242	  if (error) throw error;
243	
244	  const stats: Record<string, InjectionSiteStat> = {};
245	  for (const row of data as { injection_site: string; log_date: string }[]) {
246	    const key = row.injection_site.trim().toLowerCase();
247	    const existing = stats[key];
248	    if (!existing) {
249	      stats[key] = { lastUsed: row.log_date, count30d: 1 };
250	    } else {
251	      existing.count30d += 1;
252	      if (row.log_date > existing.lastUsed) existing.lastUsed = row.log_date;
253	    }
254	  }
255	  return stats;
256	}
