265	    .select('log_date, taken')
266	    .eq('user_id', userId)
267	    .gte('log_date', toISODate(from))
268	    .lte('log_date', toISODate(to));
269	  if (error) throw error;
270	
271	  const map: Record<string, { total: number; taken: number }> = {};
272	  for (const row of data as { log_date: string; taken: boolean }[]) {
273	    const entry = (map[row.log_date] ??= { total: 0, taken: 0 });
274	    entry.total += 1;
275	    if (row.taken) entry.taken += 1;
276	  }
277	  return map;
