309	/**
310	 * The user's own most recent numbers for a given item, so adding it again does
311	 * not mean retyping it.
312	 *
313	 * This is deliberately the only thing that ever pre-fills the amount field.
314	 * The app has no recommended dose to offer — the glossary carries name,
315	 * category, mechanism, storage and route and nothing else, by design (see
316	 * legal.md). Prior entries are the user's own data being handed back to them,
317	 * which is the food-diary model the schema was built around.
318	 *
319	 * Looks at a previous schedule entry first (including deactivated ones, so
320	 * removing and re-adding remembers), then falls back to the dose log.
321	 */
322	export async function getPriorEntry(
323	  userId: string,
324	  opts: { name?: string | null; glossaryId?: string | null },
325	): Promise<PriorEntry | null> {
326	  const { name, glossaryId } = opts;
327	  if (!name && !glossaryId) return null;
328	
329	  let schedQ = supabase
330	    .from('schedule_items')
331	    .select('amount, scheduled_time, injection_site')
332	    .eq('user_id', userId);
333	  schedQ = glossaryId ? schedQ.eq('glossary_id', glossaryId) : schedQ.eq('name', name!);
334	  const { data: sched } = await schedQ.order('created_at', { ascending: false }).limit(1);
335	
336	  const s = sched?.[0];
337	  if (s) {
338	    return { ...s, source: 'schedule', lastUsed: null };
339	  }
340	
341	  let logQ = supabase
342	    .from('doses')
343	    .select('amount, scheduled_time, injection_site, log_date')
344	    .eq('user_id', userId);
345	  logQ = glossaryId ? logQ.eq('glossary_id', glossaryId) : logQ.eq('name', name!);
346	  const { data: logged } = await logQ.order('log_date', { ascending: false }).limit(1);
347	
348	  const d = logged?.[0];
349	  if (d) {
350	    const { log_date, ...rest } = d;
351	    return { ...rest, source: 'log', lastUsed: log_date };
352	  }
353	  return null;
354	}
