356	export async function addScheduleItem(userId: string, input: NewScheduleItem): Promise<ScheduleItem> {
357	  const { data, error } = await supabase
358	    .from('schedule_items')
359	    .insert({ user_id: userId, ...input })
360	    .select()
361	    .single();
362	
363	  // Migration 0013 adds start_date. Until it has been run the column is not
364	  // there and PostgREST rejects the whole insert (PGRST204), so fall back to
365	  // an insert without it rather than failing to save the item at all.
366	  if (error && input.start_date && /start_date/.test(error.message ?? '')) {
367	    const { start_date, ...rest } = input;
368	    void start_date;
369	    const retry = await supabase
370	      .from('schedule_items')
371	      .insert({ user_id: userId, ...rest })
372	      .select()
373	      .single();
374	    if (retry.error) throw retry.error;
375	    return retry.data as ScheduleItem;
376	  }
377	  if (error) throw error;
378	  return data as ScheduleItem;
379	}
