386	/**
387	 * Ensures today has a doses row for every active schedule item, so the
388	 * existing doses-based rendering, history, and compliance logic all keep
389	 * working unchanged. Safe to call every time Today loads — only inserts
390	 * rows that don't already exist for today.
391	 */
392	export async function ensureTodayDoses(userId: string): Promise<void> {
393	  const today = toISODate(new Date());
394	  const [{ data: items, error: itemsErr }, { data: existing, error: existingErr }] = await Promise.all([
395	    supabase.from('schedule_items').select('*').eq('user_id', userId).eq('active', true),
396	    supabase.from('doses').select('schedule_item_id').eq('user_id', userId).eq('log_date', today).not('schedule_item_id', 'is', null),
397	  ]);
398	  if (itemsErr) throw itemsErr;
399	  if (existingErr) throw existingErr;
400	
401	  const covered = new Set((existing as { schedule_item_id: string }[]).map((r) => r.schedule_item_id));
402	  const missing = (items as ScheduleItem[]).filter(
403	    // an item set to begin later simply has no row today yet
404	    (item) => !covered.has(item.id) && scheduleStart(item) <= today,
405	  );
406	  if (missing.length === 0) return;
407	
408	  const { error: insertErr } = await supabase.from('doses').insert(
409	    missing.map((item) => ({
410	      user_id: userId,
411	      schedule_item_id: item.id,
412	      glossary_id: item.glossary_id,
413	      name: item.name,
414	      amount: item.amount,
415	      log_date: today,
416	      scheduled_time: item.scheduled_time,
417	      injection_site: item.injection_site,
418	    })),
419	  );
420	  if (insertErr) throw insertErr;
421	}
