462	/** Reference intakes for a set of entries, all bands and both sexes. */
463	export async function getNutrientReference(glossaryIds: string[]): Promise<Record<string, NutrientReference[]>> {
464	  if (glossaryIds.length === 0) return {};
465	  const { data, error } = await supabase
