475	/**
476	 * The row that applies to this person. Sex-specific first, then the 'any' row,
477	 * so a nutrient that differs by sex uses the right one and a nutrient that does
478	 * not still resolves.
479	 */
480	export function pickReference(
481	  rows: NutrientReference[] | undefined,
482	  age: number | null | undefined,
483	  sex: 'm' | 'f' | 'na' | null | undefined,
484	): NutrientReference | null {
485	  if (!rows?.length) return null;
486	  const band = age == null ? '19-50' : age < 19 ? '14-18' : age < 51 ? '19-50' : '51+';
487	  const s = sex === 'm' || sex === 'f' ? sex : 'any';
488	  return (
489	    rows.find((r) => r.age_band === band && r.sex === s) ??
490	    rows.find((r) => r.age_band === band && r.sex === 'any') ??
491	    rows.find((r) => r.age_band === '19-50' && r.sex === s) ??
492	    rows.find((r) => r.age_band === '19-50' && r.sex === 'any') ??
493	    null
494	  );
495	}
