509	// ============================================================================
510	// Stacks — one default stack per user, created lazily
511	// ============================================================================
512	
513	const DEFAULT_STACK_NAME = 'My Stack';
514	
515	async function ensureDefaultStack(userId: string): Promise<string> {
516	  const { data: existing, error: selErr } = await supabase
517	    .from('stacks')
518	    .select('id')
519	    .eq('user_id', userId)
520	    .eq('name', DEFAULT_STACK_NAME)
521	    .maybeSingle();
522	  if (selErr) throw selErr;
523	  if (existing) return existing.id as string;
524	
525	  const { data: created, error: insErr } = await supabase
526	    .from('stacks')
527	    .insert({ user_id: userId, name: DEFAULT_STACK_NAME })
528	    .select('id')
529	    .single();
530	  if (insErr) throw insErr;
531	  return created.id as string;
532	}
533	
534	export async function isInStack(userId: string, glossaryId: string): Promise<boolean> {
535	  const { data, error } = await supabase
536	    .from('stack_items')
537	    .select('id, stacks!inner(user_id)')
538	    .eq('glossary_id', glossaryId)
539	    .eq('stacks.user_id', userId)
540	    .maybeSingle();
541	  if (error) throw error;
542	  return !!data;
543	}
544	
545	/** Batch version of isInStack, for checking a whole result list in one query. */
546	export async function getStackMembership(userId: string, glossaryIds: string[]): Promise<Set<string>> {
547	  if (glossaryIds.length === 0) return new Set();
548	  const { data, error } = await supabase
549	    .from('stack_items')
550	    .select('glossary_id, stacks!inner(user_id)')
551	    .in('glossary_id', glossaryIds)
552	    .eq('stacks.user_id', userId);
553	  if (error) throw error;
554	  return new Set((data as { glossary_id: string }[]).map((row) => row.glossary_id));
555	}
556	
557	export async function addToStack(userId: string, glossaryId: string): Promise<void> {
558	  const stackId = await ensureDefaultStack(userId);
559	  const already = await isInStack(userId, glossaryId);
560	  if (already) return;
561	  const { error } = await supabase.from('stack_items').insert({ stack_id: stackId, glossary_id: glossaryId });
562	  if (error) throw error;
563	}
564	
565	export async function getStack(userId: string): Promise<StackItem[]> {
566	  const { data, error } = await supabase
567	    .from('stack_items')
568	    .select(
569	      'id, glossary_id, expires_on, vial_total_ml, ml_per_dose, vial_started_on, glossary:glossary_id(*), stacks!inner(user_id)',
570	    )
571	    .eq('stacks.user_id', userId)
572	    .order('created_at', { ascending: false });
573	  if (error) throw error;
574	  return (data as unknown as (StackItem & { stacks: unknown })[]).map(({ stacks: _stacks, ...rest }) => rest);
575	}
576	
577	export async function removeFromStack(stackItemId: string): Promise<void> {
578	  const { error } = await supabase.from('stack_items').delete().eq('id', stackItemId);
579	  if (error) throw error;
580	}
581	
582	export async function setStackItemExpiry(stackItemId: string, expiresOn: string | null): Promise<void> {
583	  const { error } = await supabase.from('stack_items').update({ expires_on: expiresOn }).eq('id', stackItemId);
584	  if (error) throw error;
585	}
586	
587	/** Vial size and draw-per-dose the user computed for themselves (e.g. via the reconstitution calculator). */
588	export async function setVialInfo(stackItemId: string, info: VialInfo): Promise<void> {
589	  const { error } = await supabase.from('stack_items').update(info).eq('id', stackItemId);
590	  if (error) throw error;
591	}
592	
593	export async function clearVialInfo(stackItemId: string): Promise<void> {
594	  const { error } = await supabase
595	    .from('stack_items')
596	    .update({ vial_total_ml: null, ml_per_dose: null, vial_started_on: null })
597	    .eq('id', stackItemId);
598	  if (error) throw error;
599	}
600	
601	/** How many doses under this name were actually taken on or after a given date — used to work out what's left in a vial. */
602	export async function getTakenCountSince(userId: string, name: string, sinceDate: string): Promise<number> {
603	  const { count, error } = await supabase
604	    .from('doses')
605	    .select('id', { count: 'exact', head: true })
606	    .eq('user_id', userId)
607	    .eq('name', name)
608	    .eq('taken', true)
609	    .gte('log_date', sinceDate);
610	  if (error) throw error;
611	  return count ?? 0;
612	}
613	
614	// ============================================================================
615	// Progress notes — user's own text, measurements, and photos. The app has
616	// no opinion on these values; it only stores and displays what was entered.
617	// ============================================================================
618	
619	export async function getProgressNotes(userId: string): Promise<ProgressNote[]> {
620	  const { data, error } = await supabase
621	    .from('progress_notes')
622	    .select('*')
623	    .eq('user_id', userId)
624	    .order('note_date', { ascending: false })
625	    .limit(60);
626	  if (error) throw error;
627	  return data as ProgressNote[];
628	}
629	
630	export async function addProgressNote(userId: string, input: NewProgressNote): Promise<ProgressNote> {
631	  const { data, error } = await supabase
632	    .from('progress_notes')
633	    .insert({ user_id: userId, ...input })
634	    .select()
635	    .single();
636	  if (error) throw error;
637	  return data as ProgressNote;
638	}
639	
640	export async function uploadProgressPhoto(userId: string, file: File): Promise<string> {
641	  const ext = file.name.split('.').pop() || 'jpg';
642	  const path = `${userId}/${crypto.randomUUID()}.${ext}`;
643	  const { error } = await supabase.storage.from('progress-photos').upload(path, file);
644	  if (error) throw error;
645	  return path;
646	}
647	
648	export async function getProgressPhotoUrl(path: string): Promise<string> {
649	  const { data, error } = await supabase.storage.from('progress-photos').createSignedUrl(path, 3600);
650	  if (error) throw error;
651	  return data.signedUrl;
652	}
