16	/* ── sleep ───────────────────────────────────────────────────────────── */
17	
18	const DIAL = 236;
19	const DIAL_R = 94;
20	const DIAL_STROKE = 18;
21	const HANDLE_R = 13;
22	/** minutes the handles snap to */
23	const SNAP = 5;
24	
25	const angleOf = (t: string) => (toMin(t) / 1440) * 360;
26	const onRing = (deg: number, r = DIAL_R) => {
27	  const rad = ((deg - 90) * Math.PI) / 180;
28	  return [DIAL / 2 + r * Math.cos(rad), DIAL / 2 + r * Math.sin(rad)] as const;
29	};
30	const timeOf = (deg: number) => {
31	  const mins = Math.round((((deg % 360) + 360) % 360 / 360) * 1440 / SNAP) * SNAP;
32	  const m = mins % 1440;
33	  return `${String(Math.floor(m / 60)).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`;
34	};
