87	    const t = timeOf(((toMin(cur) + delta + 1440) % 1440 / 1440) * 360);
88	    onChange(which === 'wake' ? { wake: t, sleep } : { wake, sleep: t });
89	  };
90	
91	  return (
92	    <Screen scroll footer={<Cta onClick={onNext}>Continue</Cta>}>
93	      <Title>Your day, part one</Title>
94	      <Sub>Drag either end of the ring. We schedule around the window, not the minute.</Sub>
95	
96	      <div className="ob-dial-wrap">
97	        <svg
98	          ref={svgRef}
99	          className="ob-dial"
100	          width={DIAL}
101	          height={DIAL}
102	          viewBox={`0 0 ${DIAL} ${DIAL}`}
103	          onPointerMove={move}
104	          onPointerUp={release}
105	          onPointerCancel={release}
106	        >
107	          <circle cx={c} cy={c} r={DIAL_R} fill="none" stroke="var(--card)" strokeWidth={DIAL_STROKE} />
108	          <circle
109	            cx={c}
110	            cy={c}
111	            r={DIAL_R}
112	            fill="none"
113	            stroke="var(--accent)"
114	            strokeWidth={DIAL_STROKE}
115	            strokeLinecap="round"
116	            strokeDasharray={`${circumference * (mins / 1440)} ${circumference}`}
117	            transform={`rotate(${startDeg - 90} ${c} ${c})`}
118	          />
119	
120	          {/* twelve ticks, so the ring reads as a clock rather than a gauge */}
121	          {Array.from({ length: 12 }, (_, i) => {
122	            const [x1, y1] = onRing(i * 30, DIAL_R - DIAL_STROKE / 2 - 7);
123	            const [x2, y2] = onRing(i * 30, DIAL_R - DIAL_STROKE / 2 - (i % 3 === 0 ? 13 : 10));
124	            return <line key={i} x1={x1} y1={y1} x2={x2} y2={y2} stroke="var(--t4)" strokeWidth="2" strokeLinecap="round" />;
125	          })}
126	
127	          <Handle
128	            x={sx}
129	            y={sy}
130	            label="Go to sleep"
131	            value={sleep}
132	            onGrab={grab('sleep')}
133	            onNudge={(d) => nudge('sleep', d)}
134	          />
135	          <Handle
136	            x={wx}
137	            y={wy}
138	            label="Wake up"
139	            value={wake}
140	            onGrab={grab('wake')}
141	            onNudge={(d) => nudge('wake', d)}
142	          />
143	        </svg>
144	
145	        <div className="ob-dial-centre">
146	          <div className="ob-dial-hours">
