1	import { useState } from 'react';
2	import { Cta, OnboardIllustration, Screen, Sub, Title } from '../chrome';
3	import { PLANS, purchase, restorePurchases, type PlanId } from '../../lib/billing';
4	
5	/* ── notifications ───────────────────────────────────────────────────── */
6	
7	/**
8	 * iOS gives exactly one chance at the system prompt. Tap Don't Allow and it is
9	 * Settings-only forever, so the ask is explained here first and
10	 * requestPermission is only reached from the accent button — never on mount.
11	 */
12	export function Notifications({
13	  onDone,
14	}: {
15	  onDone: (granted: boolean) => void;
16	}) {
17	  const [busy, setBusy] = useState(false);
18	
19	  const ask = async () => {
20	    setBusy(true);
21	    try {
22	      if (typeof Notification === 'undefined') {
23	        onDone(false);
24	        return;
25	      }
26	      const res = await Notification.requestPermission();
27	      onDone(res === 'granted');
28	    } catch {
29	      onDone(false);
30	    } finally {
31	      setBusy(false);
32	    }
33	  };
34	
35	  return (
36	    <Screen
37	      center
38	      footer={
39	        <>
40	          <Cta onClick={ask} disabled={busy}>
41	            {busy ? 'Asking…' : 'Turn on reminders'}
42	          </Cta>
43	          <button className="ob-cta ob-cta-ghost" onClick={() => onDone(false)}>
44	            Not now
45	          </button>
46	        </>
47	      }
48	    >
49	      <OnboardIllustration name="bell" />
50	      <div style={{ marginTop: 30 }}>
51	        <Title>Reminders at the right times</Title>
52	        <Sub>
53	          One notification per time block — around three a day. Nothing else, ever: no streak guilt,
54	          no marketing.
55	        </Sub>
56	      </div>
57	    </Screen>
58	  );
59	}
60	
61	/* ── paywall ─────────────────────────────────────────────────────────── */
62	
63	const VALUE = [
64	  'Your whole stack in one schedule, built around your day',
65	  'A warning when two supplements shouldn’t share a slot',
66	  'The research behind every suggestion, linked',
67	];
68	
69	export function Paywall({ onDone }: { onDone: (subscribed: boolean) => void }) {
70	  const [plan, setPlan] = useState<PlanId>('annual');
71	  const [busy, setBusy] = useState<'buy' | 'restore' | null>(null);
72	  const [note, setNote] = useState<string | null>(null);
73	
74	  const buy = async () => {
75	    setBusy('buy');
76	    setNote(null);
77	    try {
78	      onDone(await purchase(plan));
79	    } finally {
80	      setBusy(null);
81	    }
82	  };
83	
84	  const restore = async () => {
85	    setBusy('restore');
86	    setNote(null);
87	    try {
88	      const ok = await restorePurchases();
89	      if (ok) onDone(true);
90	      else setNote('No previous purchase found on this account.');
91	    } finally {
92	      setBusy(null);
93	    }
94	  };
95	
96	  return (
97	    <Screen
98	      scroll
99	      footer={
100	        <>
101	          <Cta onClick={buy} disabled={busy !== null}>
102	            {busy === 'buy' ? 'One moment…' : 'Start with Pepstack'}
103	          </Cta>
104	          <div className="ob-legal-row">
105	            {/* Not optional — a missing restore path is the most common
106	                rejection reason for subscription apps. */}
107	            <button onClick={restore} disabled={busy !== null}>
108	              {busy === 'restore' ? 'Checking…' : 'Restore Purchases'}
109	            </button>
110	            <a href="/terms">Terms</a>
111	            <a href="/privacy">Privacy</a>
112	          </div>
113	        </>
114	      }
115	    >
116	      <Title>Everything, in one place</Title>
117	
118	      <div style={{ marginTop: 22 }}>
119	        {VALUE.map((v) => (
120	          <div className="ob-value" key={v}>
121	            <svg width="18" height="18" viewBox="0 0 18 18" fill="none" stroke="var(--accent)" strokeWidth="2.1" strokeLinecap="round" strokeLinejoin="round" style={{ flex: 'none', marginTop: 2 }} aria-hidden>
122	              <path d="M3.5 9.5 7 13l7.5-8" />
123	            </svg>
124	            {v}
125	          </div>
126	        ))}
127	      </div>
128	
129	      <div className="ob-plans" role="radiogroup" aria-label="Plan">
130	        {PLANS.map((p) => (
131	          <button
132	            key={p.id}
133	            role="radio"
134	            aria-checked={plan === p.id}
135	            className={`ob-plan${plan === p.id ? ' on' : ''}`}
136	            onClick={() => setPlan(p.id)}
137	          >
138	            <span>
139	              <span className="ob-card-title">
140	                {p.name}
141	                {p.badge && <span className="ob-badge">{p.badge}</span>}
142	              </span>
143	              <span className="ob-caption" style={{ display: 'block', marginTop: 4 }}>
144	                {p.note}
145	              </span>
146	            </span>
147	            <span style={{ textAlign: 'right', flex: 'none' }}>
148	              <span className="ob-card-title">{p.price}</span>
149	              <span className="ob-caption" style={{ display: 'block' }}>
150	                {p.period}
151	              </span>
152	            </span>
153	          </button>
154	        ))}
155	      </div>
