1	import { useEffect, useMemo, useRef, useState } from 'react';
2	import { Cta, OnboardIllustration, Screen, Sub, Title } from '../chrome';
3	import { GOAL_BY_ID, DEFAULT_GOAL_IDS } from '../goals';
