14	/* ── the two loading screens ─────────────────────────────────────────── */
15	
16	export function Building({
17	  variant,
18	  onDone,
19	}: {
20	  variant: 'recs' | 'schedule';
21	  onDone: () => void;
22	}) {
23	  const copy =
24	    variant === 'recs'
25	      ? {
26	          title: 'Going through the research for your goals.',
27	          lines: ['Reading the entries', 'Matching them to your goals', 'Checking for overlaps'],
28	          min: 2200,
