87	/* ── recommendations ─────────────────────────────────────────────────── */
88	
89	export interface Recommendation {
90	  id: string;
91	  name: string;
92	  why: string;
93	  route: string;
94	  selected: boolean;
95	  /** the intake that applies to this person, where one is established */
96	  amount: string;
97	}
