99	export function useRecommendations(
100	  goalIds: string[],
101	  currentStack: string[],
102	  age?: number | null,
103	  sex?: 'm' | 'f' | 'na' | null,
104	) {
105	  const [entries, setEntries] = useState<GlossaryEntry[] | null>(null);
106	  const [refs, setRefs] = useState<Record<string, NutrientReference[]>>({});
107	  useEffect(() => {
108	    listGlossary(200)
109	      .then((rows) => {
110	        setEntries(rows);
111	        return getNutrientReference(rows.map((r) => r.id));
112	      })
113	      .then((m) => m && setRefs(m))
114	      .catch(() => setEntries([]));
115	  }, []);
116	
117	  return useMemo(() => {
118	    if (!entries) return null;
119	    const ids = goalIds.length ? goalIds : DEFAULT_GOAL_IDS;
120	    const wanted = new Set(ids.flatMap((g) => GOAL_BY_ID[g]?.tags ?? []));
121	    const already = new Set(currentStack.map((s) => s.toLowerCase()));
122	
123	    /* Supplements only. Ranking peptides for a specific person is a
124	       recommendation whether or not an amount is attached, and it is the same
125	       rule the assistant is held to — enforced here in code rather than left
126	       to whatever the tag overlap happens to return. Every goal was returning
127	       two to four peptides in its top six before this. */
128	    const EVIDENCE_RANK = { strong: 0, mixed: 1, thin: 2 } as const;
129	    const rank = (e: GlossaryEntry) => EVIDENCE_RANK[e.evidence ?? 'thin'] ?? 2;
130	
131	    const scored = entries
132	      .filter((e) => (e.kind ?? 'peptide') === 'supplement')
133	      // no point suggesting what they told us they already take
134	      .filter((e) => !already.has(e.name.toLowerCase()))
135	      .map((e) => {
136	        const hits = (e.goal_tags ?? []).filter((t) => wanted.has(t));
137	        return { e, hits };
138	      })
139	      .filter((x) => x.hits.length > 0)
140	      /* Goal overlap first, then how good the evidence is. The tie-break used
141	         to be the product name, which sorted alphabetically and quietly put
142	         every brand beginning with A at the top of a list that looks like a
143	         ranking. */
144	      .sort(
145	        (a, b) =>
146	          b.hits.length - a.hits.length ||
147	          rank(a.e) - rank(b.e) ||
148	          a.e.name.localeCompare(b.e.name),
149	      );
150	
151	    const goalNames = ids.map((g) => GOAL_BY_ID[g]?.name ?? g);
152	
153	    return {
154	      picks: scored.slice(0, 6).map(({ e, hits }, i) => {
155	        const r = pickReference(refs[e.id], age, sex);
156	        return {
157	          id: e.id,
158	          name: e.name,
159	          route: e.route,
160	          amount: r?.rda != null ? `${r.rda} ${r.unit}` : '',
161	          why: `Tagged ${hits.join(' and ')} — matches ${goalNames.length > 1 ? 'your goals' : goalNames[0]?.toLowerCase()}.`,
162	          selected: i < 3,
163	        };
164	      }),
165	      leftOut: {
166	        alreadyTaking: entries
167	          .filter((e) => already.has(e.name.toLowerCase()))
168	          .map((e) => e.name),
169	        noMatch: scored.length > 6 ? scored.slice(6).map((x) => x.e.name) : [],
170	        goalNames,
171	      },
172	    };
173	  }, [entries, refs, goalIds, currentStack, age, sex]);
174	}
175	
176	export function Recommendations({
177	  goalIds,
178	  currentStack,
179	  age,
180	  sex,
181	  onDone,
182	}: {
183	  goalIds: string[];
184	  currentStack: string[];
185	  age?: number | null;
186	  sex?: 'm' | 'f' | 'na' | null;
187	  onDone: (picks: Recommendation[]) => void;
188	}) {
189	  const data = useRecommendations(goalIds, currentStack, age, sex);
190	  const [picks, setPicks] = useState<Recommendation[] | null>(null);
191	
192	  useEffect(() => {
193	    if (data && !picks) setPicks(data.picks);
194	  }, [data, picks]);
195	
196	  if (!data || !picks) {
197	    return (
198	      <Screen center>
199	        <p className="ob-sub">Loading…</p>
200	      </Screen>
201	    );
202	  }
203	
204	  const chosen = picks.filter((p) => p.selected);
205	
206	  return (
207	    <Screen
208	      scroll
209	      footer={
210	        <Cta onClick={() => onDone(chosen)} disabled={chosen.length === 0}>
211	          Create schedule
212	        </Cta>
213	      }
214	    >
215	      <Title>What we found</Title>
216	      <Sub>
217	        Matched to {data.leftOut.goalNames.join(' and ').toLowerCase()}, ranked by how many of your
218	        goals each one covers and then by the strength of the evidence. Untick anything you
219	        don’t want.
220	      </Sub>
221	
222	      <div className="ob-recs">
223	        {picks.map((r) => (
224	          <button
225	            key={r.id}
226	            className={`ob-rec${r.selected ? ' on' : ''}`}
227	            aria-pressed={r.selected}
228	            onClick={() =>
229	              setPicks((ps) => ps!.map((p) => (p.id === r.id ? { ...p, selected: !p.selected } : p)))
230	            }
231	          >
232	            <span className="ob-rec-main">
233	              <span className="ob-card-title">{r.name}</span>
234	              {/* The app holds no dose for anything and will not invent one --
235	                  the glossary carries category, mechanism, storage and route,
236	                  never an amount. See legal.md. The slot stays, labelled. */}
237	              <span className="ob-rec-dose">
238	                {r.amount ? `${r.amount} a day · ${r.route}` : `${r.route} · you set the amount`}
239	              </span>
240	              <span className="ob-rec-why">{r.why}</span>
241	              <span className="ob-rec-link">Read the research →</span>
242	            </span>
243	            <span className={`ob-tick${r.selected ? ' on' : ''}`}>
244	              {r.selected && (
245	                <svg width="12" height="12" viewBox="0 0 12 12" fill="none" stroke="var(--bg)" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
246	                  <path d="M2.5 6.2 4.8 8.5 9.5 3.5" />
247	                </svg>
248	              )}
249	            </span>
250	          </button>
251	        ))}
252	      </div>
253	
254	      {/* The part people screenshot. Do not cut it. */}
255	      <div className="ob-left-out">
256	        <h2>What was left out</h2>
257	        {data.leftOut.alreadyTaking.length > 0 && (
258	          <p>
259	            <b>Already in your stack:</b> {data.leftOut.alreadyTaking.join(', ')}. No point suggesting
260	            what you are taking.
261	          </p>
262	        )}
263	        {data.leftOut.noMatch.length > 0 && (
264	          <p>
265	            <b>Matched but ranked lower:</b> {data.leftOut.noMatch.slice(0, 6).join(', ')}. Fewer of
266	            your goals matched their tags.
267	          </p>
268	        )}
269	        <p>
270	          Everything else in the library is tagged for goals you did not pick. Nothing was excluded
271	          for being unpopular or unprofitable — the ranking is goal-tag overlap and nothing else.
272	        </p>
273	      </div>
274	    </Screen>
275	  );
276	}
277	
278	/* ── the draggable schedule ──────────────────────────────────────────── */
279	
280	interface Slot {
281	  id: string;
282	  name: string;
283	  time: string;
284	}
285	
286	const buildSlots = (meals: Meal[], wake: string, sleep: string): Slot[] => {
287	  const s: Slot[] = [{ id: 'morning', name: 'Morning', time: wake }];
288	  for (const m of [...meals].sort((a, b) => toMinutes(a.time) - toMinutes(b.time))) {
289	    s.push({ id: m.id, name: m.name, time: m.time });
290	  }
291	  s.push({ id: 'winddown', name: 'Wind-down', time: fromMinutes(toMinutes(sleep) - 60) });
292	  const seen = new Set<string>();
293	  return s.filter((x) => (seen.has(x.time) ? false : (seen.add(x.time), true)));
294	};
295	
296	export function ScheduleBuilder({
297	  picks,
298	  meals,
299	  wake,
300	  sleep,
301	  onDone,
302	}: {
303	  picks: Recommendation[];
304	  meals: Meal[];
305	  wake: string;
306	  sleep: string;
307	  onDone: (schedule: { id: string; time: string }[]) => void;
308	}) {
309	  const slots = useMemo(() => buildSlots(meals, wake, sleep), [meals, wake, sleep]);
310	  const [placed, setPlaced] = useState<Record<string, string>>(() =>
311	    Object.fromEntries(picks.map((p, i) => [p.id, slots[i % slots.length].id])),
312	  );
313	  const [dragging, setDragging] = useState<string | null>(null);
314	  const [over, setOver] = useState<{ slot: string; bad: boolean } | null>(null);
315	  const [shake, setShake] = useState<string | null>(null);
316	  const [message, setMessage] = useState<string | null>(null);
317	  const hold = useRef<number | null>(null);
318	
319	  const ctx = { mealTimes: meals.map((m) => m.time), sleepTime: sleep };
320	  const slotById = Object.fromEntries(slots.map((s) => [s.id, s]));
321	
322	  const itemsIn = (slotId: string) => picks.filter((p) => placed[p.id] === slotId);
323	
324	  const others = (movingId: string): ScheduledItem[] =>
325	    picks
326	      .filter((p) => p.id !== movingId)
327	      .map((p) => ({ id: p.id, name: p.name, time: slotById[placed[p.id]]?.time ?? wake }));
328	
329	  const tryDrop = (id: string, slotId: string) => {
330	    const p = picks.find((x) => x.id === id)!;
331	    const target = slotById[slotId];
332	    const violations = checkPlacement({ id, name: p.name, time: target.time }, target.time, others(id), ctx);
333	    const blocking = violations.find((v) => v.severity === 'block');
334	    if (blocking) {
335	      // springs back, shakes, and says which rule -- the shake on its own
336	      // communicates nothing and fails accessibility
337	      setShake(id);
338	      setMessage(blocking.message);
339	      setTimeout(() => setShake(null), 420);
340	      return;
341	    }
342	    setPlaced((m) => ({ ...m, [id]: slotId }));
343	    setMessage(violations[0]?.message ?? null);
344	  };
345	
346	  const startHold = (id: string) => {
347	    hold.current = window.setTimeout(() => setDragging(id), 200);
348	  };
349	  const cancelHold = () => {
350	    if (hold.current) clearTimeout(hold.current);
351	    hold.current = null;
352	  };
353	
354	  const onMove = (e: React.PointerEvent) => {
355	    if (!dragging) return;
356	    const el = document.elementFromPoint(e.clientX, e.clientY)?.closest('[data-slot]') as HTMLElement | null;
357	    if (!el) return setOver(null);
358	    const slotId = el.dataset.slot!;
359	    const p = picks.find((x) => x.id === dragging)!;
360	    const t = slotById[slotId];
361	    const bad = checkPlacement({ id: dragging, name: p.name, time: t.time }, t.time, others(dragging), ctx).some(
362	      (v) => v.severity === 'block',
363	    );
364	    setOver({ slot: slotId, bad });
365	  };
366	
367	  const onUp = () => {
368	    cancelHold();
369	    if (dragging && over) tryDrop(dragging, over.slot);
370	    setDragging(null);
371	    setOver(null);
372	  };
373	
374	  return (
375	    <Screen
376	      scroll
377	      footer={<Cta onClick={() => onDone(picks.map((p) => ({ id: p.id, time: slotById[placed[p.id]].time })))}>Start</Cta>}
378	    >
379	      <Title>Your schedule</Title>
380	      <Sub>Press and hold a card to move it. We’ll say if something can’t go there.</Sub>
381	
382	      <div className="ob-slots" onPointerMove={onMove} onPointerUp={onUp} onPointerCancel={onUp}>
383	        {slots.map((s) => (
384	          <div key={s.id}>
385	            <div className="ob-slot-head">
386	              <span className="ob-slot-name">{s.name}</span>
387	              <span className="ob-slot-time">{s.time}</span>
388	            </div>
389	            <div
390	              data-slot={s.id}
391	              className={`ob-slot${over?.slot === s.id ? (over.bad ? ' over-bad' : ' over') : ''}`}
392	            >
393	              {itemsIn(s.id).length === 0 && <div className="ob-slot-empty">Nothing here</div>}
394	              {itemsIn(s.id).map((p) => (
395	                <div
396	                  key={p.id}
397	                  className={`ob-dose-card${dragging === p.id ? ' lifted' : ''}${shake === p.id ? ' shake' : ''}`}
398	                  onPointerDown={() => startHold(p.id)}
399	                  onPointerUp={cancelHold}
400	                  onContextMenu={(e) => e.preventDefault()}
401	                >
402	                  <span className="ob-dose-time">{s.time}</span>
403	                  <span style={{ flex: 1, minWidth: 0 }}>
404	                    <span className="ob-card-title" style={{ display: 'block' }}>
405	                      {p.name}
406	                    </span>
407	                    <span className="ob-caption">{p.route} · you set the amount</span>
408	                  </span>
409	                  <svg className="ob-dose-grip" width="16" height="16" viewBox="0 0 16 16" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" aria-hidden>
410	                    <path d="M3 5.5h10M3 10.5h10" />
411	                  </svg>
412	                </div>
413	              ))}
414	            </div>
415	          </div>
416	        ))}
417	      </div>
418	
419	      {message && (
420	        <div className="ob-conflict" role="alert" aria-live="assertive">
421	          {message}
422	        </div>
423	      )}
424	    </Screen>
425	  );
426	}
427	
428	/* ── done ────────────────────────────────────────────────────────────── */
429	
430	export function Done({ onFinish }: { onFinish: () => void }) {
431	  useEffect(() => {
432	    const t = setTimeout(onFinish, 1400);
433	    return () => clearTimeout(t);
434	  }, [onFinish]);
435	
436	  return (
437	    <Screen center>
438	      <OnboardIllustration name="done" size={110} />
439	      <div style={{ marginTop: 26 }}>
440	        <Title>You’re set</Title>
441	        <Sub>Your first day is on the Today screen.</Sub>
442	      </div>
443	    </Screen>
444	  );
445	}
