  const index = FLOW.indexOf(step);
  return (
    <div
      className="ob-progress"
      role="progressbar"
      aria-valuemin={1}
      aria-valuemax={FLOW.length}
      aria-valuenow={index + 1}
      aria-label={`Step ${index + 1} of ${FLOW.length}`}
    >
      {FLOW.map((s, i) => (
        <span key={s} className={`ob-seg${i <= index ? ' on' : ''}`} />
      ))}
    </div>
  );
}

