2	import {
3	  getGlossaryResearch,
4	  pickReference,
5	  type GlossaryEntry,
6	  type GlossaryResearch,
7	  type NutrientReference,
8	} from '../lib/api';
9	import { EVIDENCE, Pill, ROUTE_LABEL, TIMING_LABEL } from '../components/Pills';
10	import { IconChevron, IconCheck, IconChat, IconDoc, IconPlus } from '../components/Icons';
11	
12	/** "11 mg" — what applies to this person, or null when nothing is established. */
13	export function doseLabel(
14	  refs: NutrientReference[] | undefined,
15	  age: number | null | undefined,
16	  sex: 'm' | 'f' | 'na' | null | undefined,
17	): { rda: string | null; ul: string | null } {
18	  const r = pickReference(refs, age, sex);
19	  if (!r) return { rda: null, ul: null };
20	  return {
21	    rda: r.rda == null ? null : `${r.rda} ${r.unit}`,
22	    ul: r.ul == null ? null : `${r.ul} ${r.unit}`,
23	  };
24	}
25	
26	/** The year out of "1/5 · Efficacy · Nutrients, 2016". */
27	const yearOf = (meta: string | null) => meta?.match(/\b(19|20)\d{2}\b/)?.[0] ?? null;
28	
29	/**
30	 * A product in the list.
31	 *
32	 * At rest it is flush on the background against a rail, like the paper list it
33	 * replaced — name, then a row of pills. It only becomes a card once opened, so
34	 * a long list reads as a list rather than a wall of boxes.
35	 */
36	export function ProductRow({
37	  entry,
38	  refs,
39	  age,
40	  sex,
41	  inStack,
42	  adding,
43	  expanded,
44	  onToggle,
45	  onAdd,
46	  onAsk,
47	  onAllArticles,
48	}: {
49	  entry: GlossaryEntry;
50	  refs: NutrientReference[] | undefined;
51	  age: number | null | undefined;
52	  sex: 'm' | 'f' | 'na' | null | undefined;
53	  inStack: boolean;
54	  adding: boolean;
55	  expanded: boolean;
56	  onToggle: () => void;
57	  onAdd: () => void;
58	  onAsk: () => void;
59	  onAllArticles: () => void;
60	}) {
61	  const [preview, setPreview] = useState<GlossaryResearch | null | 'loading'>(null);
62	
63	  useEffect(() => {
64	    if (!expanded || preview !== null) return;
65	    let live = true;
66	    setPreview('loading');
67	    getGlossaryResearch(entry.id)
68	      .then((rows) => live && setPreview(rows[0] ?? null))
69	      .catch(() => live && setPreview(null));
70	    return () => {
71	      live = false;
72	    };
73	    // eslint-disable-next-line react-hooks/exhaustive-deps
74	  }, [expanded]);
75	
76	  const { rda, ul } = doseLabel(refs, age, sex);
77	  const isSupp = (entry.kind ?? 'peptide') === 'supplement';
78	  const ev = entry.evidence ? EVIDENCE[entry.evidence] : null;
79	
80	  return (
81	    <div className={`prod${expanded ? ' open' : ''}`}>
82	      <button className="prod-row" onClick={onToggle} aria-expanded={expanded}>
83	        <span className="prod-main">
84	          <span className="prod-name">{entry.name}</span>
85	
86	          <span className="prod-pills">
87	            {ev && <Pill icon="evidence" tone={entry.evidence!}>{ev.label}</Pill>}
88	            {isSupp && rda && <Pill icon="dose" tone="accent">{rda} a day</Pill>}
89	            {isSupp && !rda && <Pill icon="dose">No set intake</Pill>}
90	            {ul && <Pill icon="limit">{ul} limit</Pill>}
91	            {entry.timing && <Pill icon="timing">{TIMING_LABEL[entry.timing]}</Pill>}
92	            {entry.product_form && <Pill icon="form">{entry.product_form}</Pill>}
93	            {!entry.product_form && entry.route && <Pill icon="route">{ROUTE_LABEL[entry.route] ?? entry.route}</Pill>}
94	            {entry.goal_tags?.slice(0, 2).map((g) => (
95	              <Pill icon="goal" key={g}>
96	                {g}
97	              </Pill>
98	            ))}
99	          </span>
100	        </span>
101	        <span className={`prod-chev${expanded ? ' open' : ''}`}>
102	          <IconChevron size={14} color="var(--t3)" />
103	        </span>
104	      </button>
105	
106	      {expanded && (
107	        <div className="prod-card">
108	          {/* what the grade on the pill above actually means */}
109	          {ev && (
110	            <p className="prod-evidence t-caption">
111	              <b>{ev.label}.</b> {ev.detail}
112	            </p>
113	          )}
114	
115	          {entry.timing_note && <p className="prod-evidence t-caption">{entry.timing_note}</p>}
116	
117	          {preview === 'loading' && <div className="prod-preview-empty t-caption">Loading the paper…</div>}
118	
119	          {preview && preview !== 'loading' && (
120	            <a
121	              className="prod-preview pressable"
122	              href={preview.url ?? undefined}
123	              target={preview.url ? '_blank' : undefined}
124	              rel="noreferrer"
125	            >
126	              <span className="prod-preview-head t-label">
127	                <IconDoc size={13} color="var(--t3)" />
128	                Latest paper
129	                {yearOf(preview.meta) && <span className="prod-preview-year">{yearOf(preview.meta)}</span>}
130	              </span>
131	              <span className="prod-preview-title">{preview.title}</span>
132	              {preview.meta && <span className="t-caption" style={{ color: 'var(--t2)' }}>{preview.meta}</span>}
133	              <span className="prod-preview-cta t-body-m">
134	                Read the paper
135	                <IconChevron size={12} color="var(--purple)" />
136	              </span>
137	            </a>
138	          )}
139	
140	          {preview === null && (
141	            <div className="prod-preview-empty t-caption">No paper on file for this one yet.</div>
142	          )}
143	
144	          <div className="prod-actions">
145	            <button className="prod-btn fill pressable" onClick={onAdd} disabled={inStack || adding}>
146	              {inStack ? <IconCheck size={14} color="var(--bg)" /> : <IconPlus size={14} color="var(--bg)" />}
147	              {inStack ? 'In stack' : adding ? 'Adding…' : 'Add to stack'}
148	            </button>
149	            <button className="prod-btn pressable" onClick={onAsk}>
150	              <IconChat size={14} color="var(--purple)" />
151	              Ask a question
152	            </button>
153	            <button className="prod-btn wide pressable" onClick={onAllArticles}>
154	              <IconDoc size={14} color="var(--purple)" />
155	              See more articles
156	            </button>
157	          </div>
158	        </div>
159	      )}
